#!/usr/bin/env bash
# Пакет для Arch/Manjaro из готового .deb:  bash tools/make-pacman.sh <файл.deb> <версия> <итоговый.pkg.tar.zst>
# Нужны: dpkg-deb, bsdtar (libarchive-tools), zstd
set -euo pipefail
DEB="$(realpath "$1")"; VER="$2"; OUT="$(realpath -m "$3")"
W="$(mktemp -d)"
trap 'rm -rf "$W"' EXIT
mkdir "$W/root"
dpkg-deb -x "$DEB" "$W/root"
cd "$W/root"
SIZE="$(du -sb usr | cut -f1)"
cat > .PKGINFO <<INFO
# Generated by NetLine VPN tools/make-pacman.sh
pkgname = netline-vpn
pkgbase = netline-vpn
xdata = pkgtype=pkg
pkgver = $VER-1
pkgdesc = Простой и быстрый клиент VPN и прокси
url = https://github.com/uproxe/NetLineVPN
builddate = $(date +%s)
packager = uproxe
size = $SIZE
arch = x86_64
license = MIT
depend = gtk3
depend = webkit2gtk-4.1
depend = libcap
depend = hicolor-icon-theme
optdepend = libayatana-appindicator: значок в области уведомлений
INFO
cat > .INSTALL <<'INST'
post_install() {
  setcap cap_net_admin,cap_net_raw,cap_net_bind_service+ep /usr/bin/netline-singbox 2>/dev/null || true
}
post_upgrade() {
  post_install
}
INST
OWN=(--uid 0 --gid 0 --uname root --gname root)
LANG=C bsdtar "${OWN[@]}" -czf .MTREE --format=mtree \
  --options='!all,use-set,type,uid,gid,mode,time,size,md5,sha256,link' .PKGINFO .INSTALL usr
LANG=C bsdtar "${OWN[@]}" --no-fflags -cf - .PKGINFO .INSTALL .MTREE usr | zstd -q -T0 -19 -o "$OUT"
bsdtar -xOf "$OUT" .PKGINFO | grep -E '^(pkgname|pkgver|size) '
